{
  "name": "快门时序控制组件",
  "name_en": "Shutter Timing Control Component",
  "manufacturer": "",
  "description": "这是一个非物理的软件组件，用于在实验时序中表示和调度快门输出通道。它基于数字输出抽象，能够在编排实验序列时自动补偿快门开启/关闭延迟，并生成供实验控制系统执行的定时指令与代码，常用于激光束遮断、放光窗口控制等场景。",
  "description_en": "This is a non-physical software component that represents and schedules a shutter output channel within an experimental timing sequence. Built on a digital-output abstraction, it automatically compensates for shutter open/close delays during sequence programming and generates timed instructions and code for the experiment control system, commonly for beam blocking and optical exposure-window control.",
  "actions": [
    {
      "action_name": "auto-close",
      "description": "安排快门关闭指令，并自动补偿关闭延迟。",
      "description_en": "Schedule a shutter-close instruction with automatic close-delay compensation."
    },
    {
      "action_name": "auto-generate_code",
      "description": "生成该输出通道的实验控制代码或时序数据。",
      "description_en": "Generate experiment-control code or timing data for this output channel."
    },
    {
      "action_name": "auto-open",
      "description": "安排快门打开指令，并自动补偿开启延迟。",
      "description_en": "Schedule a shutter-open instruction with automatic open-delay compensation."
    },
    {
      "action_name": "auto-get_change_times",
      "description": "获取状态变化时间。",
      "description_en": "get state change times"
    },
    {
      "action_name": "auto-clock_limit",
      "description": "获取时钟速率限制。",
      "description_en": "Get the clock rate limit."
    },
    {
      "action_name": "auto-trigger_delay",
      "description": "获取触发延迟。",
      "description_en": "Get the trigger delay."
    },
    {
      "action_name": "auto-wait_delay",
      "description": "获取等待延迟。",
      "description_en": "Get the wait delay."
    },
    {
      "action_name": "auto-get_all_outputs",
      "description": "获取全部输出对象。",
      "description_en": "Get all output objects."
    },
    {
      "action_name": "auto-apply_calibration",
      "description": "应用校准参数到输出指令。",
      "description_en": "Apply calibration parameters to the output instructions."
    },
    {
      "action_name": "auto-instruction_to_string",
      "description": "将输出指令转换为字符串表示。",
      "description_en": "Convert an output instruction to its string representation."
    },
    {
      "action_name": "auto-add_instruction",
      "description": "添加一条输出时序指令。",
      "description_en": "Add an output timing instruction."
    },
    {
      "action_name": "auto-do_checks",
      "description": "执行输出配置和时序检查。",
      "description_en": "Perform output configuration and timing checks."
    },
    {
      "action_name": "auto-offset_instructions_from_trigger",
      "description": "按触发时间偏移输出指令。",
      "description_en": "Offset output instructions relative to a trigger time."
    },
    {
      "action_name": "auto-get_ramp_times",
      "description": "获取斜坡变化时间。",
      "description_en": "Get ramp times."
    },
    {
      "action_name": "auto-make_timeseries",
      "description": "生成输出时间序列。",
      "description_en": "Generate an output time series."
    },
    {
      "action_name": "auto-expand_timeseries",
      "description": "展开输出时间序列。",
      "description_en": "Expand an output time series."
    },
    {
      "action_name": "auto-ramp",
      "description": "定义斜坡输出指令。",
      "description_en": "Define a ramp output instruction."
    },
    {
      "action_name": "auto-sine",
      "description": "定义正弦输出指令。",
      "description_en": "Define a sine output instruction."
    },
    {
      "action_name": "auto-sine_ramp",
      "description": "定义正弦斜坡输出指令。",
      "description_en": "Define a sine-ramp output instruction."
    },
    {
      "action_name": "auto-sine4_ramp",
      "description": "定义四次正弦斜坡输出指令。",
      "description_en": "Define a sine4 ramp output instruction."
    },
    {
      "action_name": "auto-sine4_reverse_ramp",
      "description": "定义反向四次正弦斜坡输出指令。",
      "description_en": "Define a reverse sine4 ramp output instruction."
    },
    {
      "action_name": "auto-exp_ramp",
      "description": "定义指数斜坡输出指令。",
      "description_en": "Define an exponential ramp output instruction."
    },
    {
      "action_name": "auto-exp_ramp_t",
      "description": "定义带时间参数的指数斜坡输出指令。",
      "description_en": "Define a time-parameterized exponential ramp output instruction."
    },
    {
      "action_name": "auto-piecewise_accel_ramp",
      "description": "定义分段加速度斜坡输出指令。",
      "description_en": "Define a piecewise-acceleration ramp output instruction."
    },
    {
      "action_name": "auto-square_wave",
      "description": "定义方波输出指令。",
      "description_en": "Define a square-wave output instruction."
    },
    {
      "action_name": "auto-square_wave_levels",
      "description": "定义带电平参数的方波输出指令。",
      "description_en": "Define a square-wave output instruction with specified levels."
    },
    {
      "action_name": "auto-customramp",
      "description": "定义自定义斜坡输出指令。",
      "description_en": "Define a custom ramp output instruction."
    },
    {
      "action_name": "auto-constant",
      "description": "定义常量输出值。",
      "description_en": "Define a constant output value."
    },
    {
      "action_name": "auto-static_value",
      "description": "定义静态输出值。",
      "description_en": "Define a static output value."
    },
    {
      "action_name": "auto-go_high",
      "description": "将数字输出置为高电平。",
      "description_en": "Set the digital output high."
    },
    {
      "action_name": "auto-go_low",
      "description": "将数字输出置为低电平。",
      "description_en": "Set the digital output low."
    },
    {
      "action_name": "auto-enable",
      "description": "使能输出通道。",
      "description_en": "Enable the output channel."
    },
    {
      "action_name": "auto-disable",
      "description": "禁用输出通道。",
      "description_en": "Disable the output channel."
    },
    {
      "action_name": "auto-repeat_pulse_sequence",
      "description": "定义重复脉冲序列。",
      "description_en": "Define a repeated pulse sequence."
    },
    {
      "action_name": "auto-trigger",
      "description": "安排触发输出指令。",
      "description_en": "Schedule a trigger output instruction."
    },
    {
      "action_name": "auto-add_device",
      "description": "添加子设备或关联输出对象。",
      "description_en": "Add a child device or associated output object."
    },
    {
      "action_name": "auto-setamp",
      "description": "设置输出幅度。",
      "description_en": "Set the output amplitude."
    },
    {
      "action_name": "auto-setfreq",
      "description": "设置输出频率。",
      "description_en": "Set the output frequency."
    },
    {
      "action_name": "auto-setphase",
      "description": "设置输出相位。",
      "description_en": "Set the output phase."
    },
    {
      "action_name": "auto-pulse",
      "description": "定义脉冲输出指令。",
      "description_en": "Define a pulse output instruction."
    }
  ],
  "tag_hints": [
    "shutter timing",
    "digital output sequencing",
    "delay compensation",
    "labscript experiment control",
    "HDF5 code generation",
    "trigger scheduling"
  ]
}

